import{_ as d,o as a,c as o,ak as e}from"./chunks/framework.DKi5cyCJ.js";const _=JSON.parse('{"title":"内存、启动与链接","description":"向量表、data 与 bss、链接脚本、跳转应用、HardFault 栈帧","frontmatter":{"title":"内存、启动与链接","description":"向量表、data 与 bss、链接脚本、跳转应用、HardFault 栈帧","date":"2026-10-20T00:00:00.000Z"},"headers":[],"relativePath":"pages/blog/2026-10-20-内存启动与链接.md","filePath":"pages/blog/2026-10-20-内存启动与链接.md"}'),l={name:"pages/blog/2026-10-20-内存启动与链接.md"};function s(r,t,c,i,p,n){return a(),o("div",null,[...t[0]||(t[0]=[e('<h1 id="内存、启动与链接" tabindex="-1">内存、启动与链接 <a class="header-anchor" href="#内存、启动与链接" aria-label="Permalink to &quot;内存、启动与链接&quot;">​</a></h1><blockquote><p>系列目录：<a href="/pages/blog/2026-10-20-嵌入式驱动面试手册.html">嵌入式驱动面试手册</a></p></blockquote><p>上电后不会直接进入 main。Cortex-M 从向量表取出栈顶和复位地址，进入 Reset_Handler。</p><div class="blog-flow"><div class="blog-flow-row"><div class="blog-flow-node">向量表[0] → MSP</div><div class="blog-flow-arrow">→</div><div class="blog-flow-node">向量表[1] → PC</div><div class="blog-flow-arrow">→</div><div class="blog-flow-node">拷贝 .data</div><div class="blog-flow-arrow">→</div><div class="blog-flow-node">清零 .bss</div><div class="blog-flow-arrow">→</div><div class="blog-flow-node accent">SystemInit → main</div></div></div><p>复位向量的最低位必须是 1，表示 Thumb。CPU 使用的地址是清掉这一位之后的值。</p><table tabindex="0"><thead><tr><th>对象</th><th>放在哪</th></tr></thead><tbody><tr><td>函数、const</td><td>只在 Flash</td></tr><tr><td>有初值的全局变量</td><td>Flash 存初值，启动后拷到 RAM</td></tr><tr><td>未初始化或初值为 0 的全局变量</td><td>只占 RAM，启动时清零</td></tr><tr><td>局部变量</td><td>栈，从 RAM 顶向下长</td></tr><tr><td>malloc</td><td>堆，从 bss 末尾向上长</td></tr></tbody></table><p>STM32 从主 Flash 启动时，链接地址一般是 <code>0x08000000</code>。<code>0x00000000</code> 在启动阶段会别名到 Flash。应用仍要把向量表偏移指到真实地址。</p><p>栈和堆相向增长。map 文件里的剩余 RAM 不含运行时的栈深。栈溢出先破坏堆，再改写全局变量。局部大数组是常见原因。</p><p>从 Bootloader 跳到 <code>0x08004000</code> 时，先确认栈顶落在 SRAM（常见判断是与 <code>0x2FFE0000</code> 相与后等于 <code>0x20000000</code>），复位向量最低位为 1，然后设置向量表偏移和 MSP 再跳转。应用里的向量表偏移也要指向自己。</p><p>HardFault 压栈顺序是 R0、R1、R2、R3、R12、LR、PC、xPSR。PC 在栈指针加 24。用 LR 的 bit2 判断现场在 PSP 还是 MSP。CFSR 在 <code>0xE000ED28</code>。HFSR 的 FORCED 位置位时，真正原因在 CFSR。中断函数名写错会链到默认死循环，现象是卡死而不是 HardFault。</p><p><a href="/pages/blog/2026-10-20-嵌入式驱动面试手册.html">返回目录</a></p>',11)])])}const v=d(l,[["render",s]]);export{_ as __pageData,v as default};
